--
-- Table structure for table `mrm_matches`
--

DROP TABLE IF EXISTS `mrm_matches`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `mrm_matches` (
  `id` int NOT NULL AUTO_INCREMENT,
  `region` int NOT NULL,
  `band1_id` int NOT NULL,
  `band1_votes` int NOT NULL DEFAULT '0',
  `band2_id` int NOT NULL,
  `band2_votes` int NOT NULL DEFAULT '0',
  `last_updated` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `start_time` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `end_time` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `winner_id` int NOT NULL DEFAULT '0',
  `show_score` tinyint(1) NOT NULL,
  `sponsor` text,
  `sponsor_msg` varchar(3000) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=64 DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

