INSERT INTO `yearendstaff` VALUES (3,26,'<table width=\"100%\" border=\"0\">\r\n  <tr>\r\n    <td width=\"50%\" valign=\"top\" bgcolor=\"#CCCCCC\"><strong><font size=5>Rob Huff</font></strong><br>\r\n      <font size=3><em><b>Transmission</b><br>Thursdays 7-11pm & Saturdays 6-8pm</em></font>\r\n<p><u><strong><font size=3>Top 10 Albums</font></strong></u><br />\r\n1. Chromatics - <em>Kill For Love </em><br />\r\n2. Frank Ocean - <em>Channel Orange </em><br />\r\n3. Perfume Genius - <em>Put Your Back N 2 It </em><br />\r\n4. Grimes - <em>Visions</em><br />\r\n5. Fiona Apple - <em>The Idler Wheelâ?¦ </em><br />\r\n6. Susanne SundfÃ¸r - <em>The Silicone Veil</em><br />\r\n7. Beach House - <em>Bloom</em><br />\r\n8. Grizzly Bear - <em>Shields</em><br />\r\n9. Jessie Ware - <em>Devotion</em><br />\r\n10. Saint Etienne - <em>Words and Music by Saint Etienne</em></p></td>\r\n    <td width=\"50%\" valign=\"top\" bgcolor=\"#CCCCCC\"><u><strong><font size=3>Top 20 Songs</font></strong></u><br />\r\n1. Frank Ocean - Bad Religion<br />\r\n2. Chromatics - Back From the Grave<br />\r\n3. Grimes - Oblivion<br />\r\n4. Chairlift - I Belong in Your Arms<br />\r\n5. Grizzly Bear - Yet Again<br />\r\n6. Jessie Ware - Wildest Moments<br />\r\n7. Beach House - Myth<br />\r\n8. Japandroids - Continuous Thunder<br />\r\n9. Sky Ferreira - Everything is Embarrassing<br />\r\n10. Hot Chip - Let Me Be Him<br />\r\n11. Death Grips - Hacker<br />\r\n12. Susanne SundfÃ¸r - White Foxes<br />\r\n13. Miguel - Adorn<br />\r\n14. Chromatics - Cherry<br />\r\n15. Perfume Genius - Floating Spit<br />\r\n16. Tame Impala - Feels Like We Only Go Backwards<br />\r\n17. AlunaGeorge - Your Drums, Your Love<br />\r\n18. Kendrick Lamar - Real (feat. Anna Wise)<br />\r\n19. How to Dress Well - & It Was You<br />\r\n20. Laurel Halo - Light + Space</td>\r\n  </tr>\r\n</table>'),(5,16,'<table width=\"100%\" border=\"0\">\r\n  <tr>\r\n    <td width=\"50%\" valign=\"top\" bgcolor=\"#CCCCCC\"><strong><font size=5>John